  "start.voiceDisclosure": "ਆਵਾਜ਼ ਤੁਹਾਡੇ ਮਾਈਕ੍ਰੋਫੋਨ ਦੀ ਵਰਤੋਂ ਕਰਦੀ ਹੈ। ਬ੍ਰਾਊਜ਼ਰ ਸਪੀਚ ਪਛਾਣ ਦੀ ਪ੍ਰਕਿਰਿਆ ਤੁਹਾਡੇ ਬ੍ਰਾਊਜ਼ਰ ਵਿਕਰੇਤਾ ਦੀ ਸਪੀਚ ਸੇਵਾ ਦੁਆਰਾ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ; ਰਿਕਾਰਡ ਕੀਤੀ ਆਵਾਜ਼ ਮੋਡ ਰਿਕਾਰਡਿੰਗ ਨੂੰ Kavach ਦੇ ਕੌਂਫਿਗਰ ਕੀਤੇ ਟ੍ਰਾਂਸਕ੍ਰਿਪਸ਼ਨ ਪ੍ਰੋਵਾਈਡਰ ਨੂੰ ਭੇਜਦਾ ਹੈ। ਆਡੀਓ ਬਾਈਟਸ ਤੁਹਾਡੀ ਕੇਸ ਫ਼ਾਈਲ ਵਿੱਚ ਨਹੀਂ ਜੋੜੇ ਜਾਂਦੇ ਹਨ, ਪਰ ਹਰੇਕ ਸੇਵਾ ਦਾ ਡੇਟਾ ਹੈਂਡਲਿੰਗ ਲਾਗੂ ਹੋ ਸਕਦਾ ਹੈ। ਆਵਾਜ਼ ਦੀ ਪ੍ਰਕਿਰਿਆ ਤੋਂ ਬਚਣ ਲਈ ਇਸ ਦੀ ਬਜਾਏ ਟਾਈਪ ਕਰੋ।",
