  "case.deleting": "ਸਥਾਨਕ ਕੇਸ ਨੂੰ ਮਿਟਾਇਆ ਜਾ ਰਿਹਾ ਹੈ…",
  "case.deleteError": "ਬ੍ਰਾਊਜ਼ਰ ਕੇਸ-ਰਿਕਾਰਡ ਨੂੰ ਮਿਟਾਏ ਜਾਣ ਨੂੰ ਸੇਵ ਨਹੀਂ ਕਰ ਸਕਿਆ, ਇਸਲਈ ਰਿਕਾਰਡ ਅਤੇ ਇਸਦੇ ਸਬੂਤ ਰੱਖੇ ਗਏ ਸਨ। ਬ੍ਰਾਊਜ਼ਰ ਸਟੋਰੇਜ ਦੀ ਜਾਂਚ ਕਰੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "case.deleteCleanupError": "ਕੇਸ ਰਿਕਾਰਡ ਹਟਾ ਦਿੱਤਾ ਗਿਆ ਸੀ, ਪਰ ਬ੍ਰਾਊਜ਼ਰ ਇਸਦੇ ਸਥਾਨਕ ਸਬੂਤ ਸਟੋਰੇਜ ਦੀ ਸਫ਼ਾਈ ਦੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਕਰ ਸਕਿਆ। ਜੇ ਸਬੂਤ ਦੀਆਂ ਬਾਈਟਸ ਬਾਕੀ ਹਨ, ਤਾਂ ਅਣਵਿਆਹੀਆਂ ਕਾਪੀਆਂ ਨੂੰ ਹਟਾਉਣ ਲਈ ਆਪਣੀਆਂ ਬ੍ਰਾਊਜ਼ਰ ਸੈਟਿੰਗਾਂ ਵਿੱਚ Kavach ਦਾ ਸਾਈਟ ਡੇਟਾ ਸਾਫ਼ ਕਰੋ; ਇਹ ਤੁਹਾਡੀ ਡਿਵਾਈਸ 'ਤੇ ਕਿਤੇ ਹੋਰ ਅਸਲ ਕਾਪੀਆਂ ਨੂੰ ਨਹੀਂ ਮਿਟਾਉਂਦਾ।",
