  "window.title": "ਰਿਕਵਰੀ ਵਿੰਡੋ",
  "window.strong": "ਹੁਣੇ ਰਿਪੋਰਟ ਕਰੋ — ਹਰ ਮਿੰਟ ਮਾਇਨੇ ਰੱਖ ਸਕਦਾ ਹੈ",
  "window.fading": "ਰਿਪੋਰਟ ਕਰਨ ਲਈ ਇੰਤਜ਼ਾਰ ਨਾ ਕਰੋ",
  "window.late": "ਫਿਰ ਵੀ ਰਿਪੋਰਟ ਕਰੋ: ਦੇਰੀ ਹਰ ਉਪਚਾਰ ਨੂੰ ਖਤਮ ਨਹੀਂ ਕਰਦੀ",
  "window.expired": "ਫਿਰ ਵੀ ਰਿਪੋਰਟ ਕਰੋ ਅਤੇ ਰਿਕਾਰਡ ਨੂੰ ਸੁਰੱਖਿਅਤ ਰੱਖੋ",
  "window.sub.strong": "1930 'ਤੇ ਕਾਲ ਕਰੋ ਅਤੇ ਤੁਰੰਤ ਆਪਣੇ ਬੈਂਕ ਨੂੰ ਸੂਚਿਤ ਕਰੋ। ਜਲਦੀ ਰਿਪੋਰਟ ਕਰਨ ਨਾਲ ਭਾਗ ਲੈਣ ਵਾਲੀਆਂ ਸੰਸਥਾਵਾਂ ਨੂੰ ਫੰਡਾਂ ਦੇ ਦੁਬਾਰਾ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਕਾਰਵਾਈ ਕਰਨ ਵਿੱਚ ਮਦਦ ਮਿਲ ਸਕਦੀ ਹੈ, ਪਰ ਨਤੀਜੇ ਵੱਖੋ-ਵੱਖਰੇ ਹੁੰਦੇ ਹਨ।",
  "window.sub.fading": "1930 'ਤੇ ਕਾਲ ਕਰੋ, ਆਪਣੇ ਬੈਂਕ ਨੂੰ ਸੂਚਿਤ ਕਰੋ ਅਤੇ ਜਿੰਨੀ ਜਲਦੀ ਹੋ ਸਕੇ ਅਧਿਕਾਰਤ ਪੋਰਟਲ 'ਤੇ ਫાઇલ ਕਰੋ। ਹਰ ਰਸੀਦ ਨੂੰ ਰੱਖੋ।",
  "window.sub.late": "ਦੇਰੀ ਤੋਂ ਬਾਅਦ ਵੀ ਰਿਪੋਰਟ ਕਰੋ। ਪੁਲਿਸ, ਬੈਂਕ ਅਤੇ ਸ਼ਿਕਾਇਤ ਰਸਤੇ ਤੱਥਾਂ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀਆਂ ਆਪਣੀਆਂ ਸਮਾਂ-ਸੀਮਾਵਾਂ 'ਤੇ ਨਿਰਭਰ ਕਰਦੇ ਹਨ; ਇੱਥੇ ਕਿਸੇ ਦੀ ਵੀ ਆਪਣੇ ਆਪ ਵਾਅਦਾ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
  "window.elapsed": "ਧੋਖਾਧੜੀ ਤੋਂ ਬਾਅਦ",
  "window.chance": "ਕੇਸ-ਪੱਧਰ ਦੀ ਰਿਕਵਰੀ ਦੀ ਸੰਭਾਵਨਾ ਪ੍ਰਕਾਸ਼ਿਤ ਨਹੀਂ ਕੀਤੀ ਗਈ ਹੈ",
  "window.noOdds": "ਕੋਈ ਪ੍ਰਤੀਸ਼ਤ ਨਹੀਂ ਦਿਖਾਈ ਗਈ ਹੈ: ਅਧਿਕਾਰਤ ਸਿਸਟਮ ਕਿਸੇ ਵਿਅਕਤੀ ਕੇਸ ਲਈ ਬਚਾਅ ਯੋਗ ਰਿਕਵਰੀ ਸੰਭਾਵਨਾ ਪ੍ਰਕਾਸ਼ਿਤ ਨਹੀਂ ਕਰਦੇ ਹਨ।",
