  "intake.vaaniBrowserNeedsConsent": "ਕਾਲ ਨੂੰ ਸਮਰੱਥ ਕਰਨ ਲਈ ਉੱਪਰ ਦਿੱਤੀਆਂ ਤਿੰਨ ਪੁਸ਼ਟੀਆਂ 'ਤੇ ਨਿਸ਼ਾਨ ਲਗਾਓ।",
  "intake.vaaniBrowserMicHint": "ਤੁਹਾਡਾ ਬ੍ਰਾਊਜ਼ਰ ਮਾਈਕ੍ਰੋਫ਼ੋਨ ਵਰਤਣ ਦੀ ਇਜਾਜ਼ਤ ਮੰਗੇਗਾ। ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇਜਾਜ਼ਤ ਨਹੀਂ ਦਿੰਦੇ, ਕੁਝ ਨਹੀਂ ਸੁਣਿਆ ਜਾਂਦਾ, ਅਤੇ ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਮਾਈਕ੍ਰੋਫ਼ੋਨ ਬੰਦ ਕਰ ਸਕਦੇ ਹੋ ਜਾਂ ਕਾਲ ਖਤਮ ਕਰ ਸਕਦੇ ਹੋ।",
  "intake.vaaniBrowserMicDenied": "ਤੁਹਾਡੇ ਬ੍ਰਾਊਜ਼ਰ ਨੇ ਮਾਈਕ੍ਰੋਫ਼ੋਨ ਬਲੌਕ ਕਰ ਦਿੱਤਾ ਹੈ, ਇਸ ਲਈ ਕਾਲ ਵਿੱਚ ਤੁਹਾਡੀ ਆਵਾਜ਼ ਨਹੀਂ ਸੁਣਾਈ ਦੇ ਰਹੀ। ਇਸ ਸਾਈਟ ਲਈ ਮਾਈਕ੍ਰੋਫ਼ੋਨ ਦੀ ਵਰਤੋਂ ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ, ਜਾਂ ਇਸ ਦੀ ਬਜਾਏ ਲਿਖਣਾ ਜਾਰੀ ਰੱਖੋ।",
  "intake.vaaniBrowserAfter": "ਜਦੋਂ ਤੁਸੀਂ ਪੂਰਾ ਕਰ ਲੈਂਦੇ ਹੋ, ਤਾਂ ਰਿਕਾਰਡਿੰਗ ਅਤੇ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਤੁਹਾਡੇ ਕੇਸ ਪੇਜ ਉੱਤੇ ਕਾਲ ਦੇ ਹੇਠਾਂ ਦਿਖਾਈ ਦਿੰਦੇ ਹਨ।",
  "call.title": "Kavach Saathi ਨਾਲ ਤੁਹਾਡੀ ਕਾਲ",
  "call.sub": "ਰਿਕਾਰਡਿੰਗ ਅਤੇ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਵੌਇਸ ਪ੍ਰੋਵਾਈਡਰ ਵੱਲੋਂ ਆਉਂਦੇ ਹਨ। ਏਜੰਟ ਨੇ ਜੋ ਵੀ ਸਮਝਿਆ ਹੈ ਉਹ ਉਦੋਂ ਤੱਕ ਇੱਕ ਡ੍ਰਾਫਟ ਹੈ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇਸ ਦੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਕਰਦੇ।",
