  "rep.e.sub": "ਪਛਾਣਕਰਤਾ ਕੱਢਣ ਲਈ ਸੁਨੇਹੇ ਪੇਸਟ ਕਰੋ। ਤੁਸੀਂ ਚੈੱਕਲਿਸਟ ਬਣਾਉਣ ਲਈ ਫ਼ਾਈਲਾਂ ਵੀ ਚੁਣ ਸਕਦੇ ਹੋ, ਪਰ ਇਹ ਡਰਾਫ਼ਟ ਸਿਰਫ਼ ਉਨ੍ਹਾਂ ਦੇ ਨਾਮ ਅਤੇ ਆਕਾਰ ਨੂੰ ਰੱਖਦਾ ਹੈ—ਫ਼ਾਈਲ ਦੀਆਂ ਬਾਈਟਾਂ ਨੂੰ ਨਹੀਂ। ਆਪਣਾ ਸਥਾਨਕ ਕੇਸ ਬਣਾਉਣ ਤੋਂ ਬਾਅਦ Evidence Vault ਵਿੱਚ ਅਸਲ ਫ਼ਾਈਲਾਂ ਨੂੰ ਦੁਬਾਰਾ ਨੱਥੀ ਕਰੋ।",
