  "rep.e.readError": "Kavach ਉਸ ਪੇਸਟ ਕੀਤੇ ਪਾਠ ਨੂੰ ਇਸ ਸਮੇਂ ਪੜ੍ਹ ਨਹੀਂ ਸਕਿਆ। ਪਾਠ ਅਜੇ ਵੀ ਸੁਰੱਖਿਅਤ ਹੈ; ਅਗਲੀ ਸਕ੍ਰੀਨ ਉੱਤੇ ਹੱਥੀਂ ਕੋਈ ਵੀ ਪਛਾਣਕਰਤਾ ਸ਼ਾਮਲ ਕਰੋ ਜਾਂ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
