  "rep.y.alsoAsks": "ਪੋਰਟਲ ਇਹਨਾਂ ਦੀ ਵੀ ਮੰਗ ਕਰਦਾ ਹੈ। ਅਸੀਂ ਇਹਨਾਂ ਦੀ ਮੰਗ ਨਹੀਂ ਕਰਦੇ — ਇੱਥੇ ਇਸਦਾ ਕਾਰਨ ਹੈ।",
  "rep.y.alsoBody": "ਇਹਨਾਂ ਵਿੱਚੋਂ ਹਰੇਕ cybercrime.gov.in ਉੱਤੇ ਲਾਜ਼ਮੀ ਹੈ: ਤੁਸੀਂ ਇਸ ਤੋਂ ਬਿਨਾਂ ਜਮ੍ਹਾਂ ਨਹੀਂ ਕਰ ਸਕਦੇ। ਧੋਖਾਧੜੀ ਦੀ ਜਾਂਚ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਇਹਨਾਂ ਵਿੱਚੋਂ ਕਿਸੇ ਦੀ ਵੀ ਲੋੜ ਨਹੀਂ ਹੈ, ਅਤੇ ਇਹਨਾਂ ਵਿੱਚੋਂ ਹਰ ਇੱਕ ਕਿਸੇ ਨੂੰ ਵੀ ਰਿਪੋਰਟ ਕਰਨ ਤੋਂ ਰੋਕਦਾ ਹੈ। ਇਹ ਇੱਥੇ ਹਨ ਜੇ ਤੁਸੀਂ ਇਹ ਦੇਣਾ ਚਾਹੁੰਦੇ ਹੋ, ਅਤੇ ਸ਼ਿਕਾਇਤ ਇਹਨਾਂ ਤੋਂ ਬਿਨਾਂ ਵੀ ਪੂਰੀ ਹੈ।",
  "rep.y.female": "ਮਹਿਲਾ",
