  "rep.r.h": "ਇਸਦੀ ਜਾਂਚ ਕਰੋ, ਫਿਰ ਆਪਣੀ ਸਥਾਨਕ ਯੋਜਨਾ ਬਣਾਓ।",
  "rep.r.sub": "ਇੱਥੋਂ ਕੁਝ ਵੀ ਬਦਲੋ। ਤੁਹਾਡੇ ਵੱਲੋਂ ਸੁਧਾਰੀ ਗਈ ਕਿਸੇ ਵੀ ਚੀਜ਼ ਨਾਲ ਬਾਕੀ ਦਾ ਹਿੱਸਾ ਨਹੀਂ ਗੁਆਚੇਗਾ।",
