  "f.mobile.was": "ਪੋਰਟਲ ਉੱਤੇ ਇਹ ਪਹਿਲਾਂ ਆਉਂਦਾ ਹੈ: OTP ਦੁਆਰਾ ਮੋਬਾਈਲ ਨੰਬਰ ਦੀ ਪੁਸ਼ਟੀ ਹੋਣ ਤੱਕ ਕੋਈ ਸ਼ੁਭਾਰੰਤ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ, ਅਤੇ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਚਾਲੀ ਖਾਨੇ ਭਰਦੇ ਹੋ, OTP ਤੀਹ ਮਿੰਟਾਂ ਵਿੱਚ ਮਿਆਦ ਪੁੱਗ ਜਾਂਦਾ ਹੈ।",
