  "ask.s2": "ਮੇਰਾ ਬੈਂਕ ਕਹਿੰਦਾ ਹੈ ਕਿ ਇਹ मेरी ਗ਼ਲਤੀ ਹੈ। ਹੁਣ ਕੀ?",
  "ask.s3": "ਪੋਰਟਲ ਕਹਿੰਦਾ ਹੈ ਨਿਪਟਾਰਾ ਹੋ ਗਿਆ (disposed)। ਕੀ ਇਹ ਖ਼ਤਮ ਹੈ?",
