  "demo.sub": "ਇੱਕ ਪ੍ਰੋਟੋਟਾਈਪ ਰਨ: ਇੱਕ ਨਾਗਰਿਕ ਧੋਖਾਧੜੀ ਦਾ ਵਰਣਨ ਕਰਦਾ է, ਕੱઢੇ ਗਏ ਤੱਥਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦਾ է ਅਤੇ ਇੱਕ ਬਿਨਾਂ ਫਾਈਲ ਕੀਤੇ ਕੇਸ ਯੋਜਨਾ ਅਤੇ ਸਪੱਸ਼ਟ ਤੌਰ 'ਤੇ ਲੇਬਲ ਕੀਤੇ ਡ੍ਰਾਫਟਾਂ ਨਾਲ ਛੱਡਦਾ ਹੈ।",
