  "g.demoMode": "ਡੈਮੋ ਮੋਡ — ਕੋਈ AI ਕੁੰਜੀ ਕੌਂਫਿਗਰ ਨਹੀਂ ਕੀਤੀ ਗਈ, ਇਸ ਲਈ ਜਵਾਬ ਇੱਕ ਬਿਲਟ-ਇਨ ਰੂਲ ਇੰਜਣ ਤੋਂ ਆਉਂਦੇ ਹਨ।",
  "nav.demo": "ਡੈਮੋ ਦੇਖੋ",
  "start.voiceNothing": "ਅਸੀਂ ਇਸਨੂੰ ਸਮਝ ਨਹੀਂ ਸਕੇ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ, ਜਾਂ ਹੇਠਾਂ ਟਾਈਪ ਕਰੋ।",
  "intake.title": "ਇੱਕ ਵਾਰ ਦੱਸੋ। ਅਸੀਂ ਤੁਹਾਡੇ ਨਾਲ ਕੇਸ ਤਿਆਰ ਕਰਦੇ ਹਾਂ।",
  "intake.sub": "ਇੱਕ ਸ਼ਾਂਤ, ਸਵਾਲ-ਦਰ-ਸਵਾਲ ਇੰਟਰਵਿਊ। ਬਿਨਾਂ ਦੁਬਾਰਾ ਸ਼ੁਰੂ ਕੀਤੇ ਚੈਟ, WhatsApp ਪ੍ਰੀਵਿਊ ਅਤੇ Vaani ਕਾਲ ਵਿੱਚਕਾਰ ਬਦਲੋ।",
  "intake.progress": "ਕੇਸ ਦੀ ਸਮਝ",
