  "intake.switch": "ਅਸੀਂ ਕਿਵੇਂ ਗੱਲ ਕਰਦੇ ਹਾਂ",
  "intake.channel.web": "ਇੱਥੇ ਚੈਟ ਕਰੋ",
  "intake.channel.whatsapp": "WhatsApp ਪ੍ਰੀਵਿਊ",
