  "intake.channel.whatsappNote": "ਉਹੀ ਅਗਵਾਈ ਵਾਲਾ ਪ੍ਰਵਾਹ ਜਾਰੀ ਰੱਖੋ",
  "intake.channel.voiceNote": "Vaani-ਲਈ ਤਿਆਰ ਵੌਇਸ ਇੰਟਰਵਿਊ",
  "intake.agentName": "Kavach ਸਾਥੀ",
  "intake.agentRole": "ਕੇਸ ਗਾਈਡ",
  "intake.boundaryQ": "ਸ਼ੁਰੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ, ਇੱਕ ਮਹੱਤਵਪੂਰਨ ਵਾਅਦਾ।",
  "intake.boundaryBody": "ਮੈਂ ਸਿਰਫ਼ ਉਹੀ ਪੁੱਛਾਂਗਾ ਜੋ ਤੁਹਾਡੇ ਕੇਸ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। ਇੱਥੇ ਕਦੇ ਵੀ ਕੋਈ OTP, PIN, ਪਾਸਵਰਡ, CVV, ਪੂਰਾ ਕਾਰਡ ਨੰਬਰ ਜਾਂ Aadhaar ਨੰਬਰ ਸਾਂਝਾ ਨਾ ਕਰੋ। Kavach ਸੁਤੰਤਰ ਹੈ, ਕੋਈ ਪੁਲਿਸ ਜਾਂ ਸਰਕਾਰੀ ਸੇਵਾ ਨਹੀਂ ਹੈ।",
  "intake.boundaryDetails": "ਇਸ ਪ੍ਰੋਟੋਟਾਈਪ ਵਿੱਚ, ਤੁਹਾਡਾ ਕੇਸ ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਸੇਵ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਜਿਹੜਾ ਟੈਕਸਟ ਤੁਸੀਂ AI ਨੂੰ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰਨ ਲਈ ਕਹਿੰਦੇ ਹੋ, ਉਹ ਕੌਂਫਿਗਰ ਕੀਤੇ ਮਾਡਲ ਪ੍ਰੋਵਾਈਡਰ ਨੂੰ ਭੇਜਿਆ ਜਾਂਦਾ ਹੈ। WhatsApp-ਸ਼ੈਲੀ ਦਾ ਪ੍ਰੀਵਿਊ ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ। ਇੱਕ ਲਾਈਵ Vaani ਟੈਸਟ ਕਾਲਬੈਕ ਲਈ ਵੱਖਰੀ ਸਹਿਮਤੀ ਅਤੇ ਇੱਕ ਅਲਾਉਲਿਸਟ ਕੀਤੇ ਨੰਬਰ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।",
  "intake.boundaryCta": "ਮੈਂ ਸਮਝ ਗਿਆ ਹਾਂ — ਸ਼ੁਰੂ ਕਰੋ",
  "intake.safetyQ": "ਕੀ ਤੁਸੀਂ, ਜਾਂ ਕੋਈ ਹੋਰ, ਇਸ ਸਮੇਂ ਤੁਰੰਤ ਸਰੀਰਕ ਖ਼ਤਰੇ ਵਿੱਚ ਹੋ?",
  "intake.safetySafe": "ਨਹੀਂ, ਮੈਂ ਇਸ ਸਮੇਂ ਸੁਰੱਖਿਅਤ ਹਾਂ",
  "intake.safetyDanger": "ਹਾਂ, ਕੋਈ ਖ਼ਤਰੇ ਵਿੱਚ ਹੋ ਸਕਦਾ ਹੈ",
  "intake.preferNot": "ਕਹਿਣਾ ਪਸੰਦ ਨਹੀਂ ਕਰਦੇ",
  "intake.emergencyH": "ਜਾਰੀ ਰੱਖਣ ਤੋਂ ਪਹਿਲਾਂ ਸੁਰੱਖਿਅਤ ਥਾਂ 'ਤੇ ਜਾਓ।",
  "intake.emergencyBody": "112 'ਤੇ ਕਾਲ ਕਰੋ ਜਾਂ ਕਿਸੇ ਸੁਰੱਖਿਅਤ ਥਾਂ 'ਤੇ ਜਾਓ ਅਤੇ ਆਪਣੇ ਕਿਸੇ ਭਰੋਸੇਮੰਦ ਵਿਅਕਤੀ ਤੋਂ ਮਦਦ ਮੰਗੋ। ਇਹ ਇੰਟਰਵਿਊ ਐਮਰਜੈਂਸੀ ਸੇਵਾਵਾਂ ਨਹੀਂ ਭੇਜ ਸਕਦੀ।",
  "intake.emergencyCall": "ਹੁਣੇ 112 'ਤੇ ਕਾਲ ਕਰੋ",
  "intake.emergencyContinue": "ਮੇਰੇ ਕੋਲ ਮਦਦ ਹੈ — ਜਾਰੀ ਰੱਖੋ",
  "intake.ageQ": "ਕੀ ਇਹ 18 ਸਾਲ ਤੋਂ ਘੱਟ ਉਮਰ ਦੇ ਕਿਸੇ ਵਿਅਕਤੀ ਬਾਰੇ ਹੈ? ਮੈਂ ਇਹ ਇਸ ਲਈ ਪੁੱਛ ਰਿਹਾ ਹਾਂ ਕਿਉਂਕਿ ਬਾਲ-ਸੁਰੱਖਿਆ ਅਤੇ ਰਿਪੋਰਟਿੰਗ ਦੇ ਨਿਯਮ ਵੱਖਰੇ ਹਨ।",
  "intake.ageAdult": "ਕੋਈ ਬੱਚਾ ਸ਼ਾਮਲ ਨਹੀਂ ਹੈ",
  "intake.ageSelfMinor": "ਮੈਂ 18 ਸਾਲ ਤੋਂ ਘੱਟ ਉਮਰ ਦਾ ਹਾਂ",
  "intake.ageChildOther": "ਇਹ ਕਿਸੇ ਹੋਰ ਬੱਚੇ ਬਾਰੇ ਹੈ",
  "intake.childH": "ਬੱਚੇ ਦੀ ਰੱਖਿਆ ਕਰੋ ਅਤੇ ਜਿਨਸੀ ਸਮੱਗਰੀ ਨੂੰ ਅੱਗੇ ਨਾ ਭੇਜੋ।",
  "intake.childBody": "ਜੇ ਕੋਈ ਬੱਚਾ ਖ਼ਤਰੇ ਵਿੱਚ ਹੈ, ਤਾਂ 112 'ਤੇ ਕਾਲ ਕਰੋ। ਬਾਲ ਸਹਾਇਤਾ ਲਈ, 1098 'ਤੇ ਕਾਲ ਕਰੋ। ਇੱਥੇ ਜਿਨਸੀ ਤਸਵੀਰਾਂ ਜਾਂ ਵੀਡੀਓਜ਼ ਨੂੰ ਅੱਪਲੋਡ, ਸੇਵ ਜਾਂ ਅੱਗੇ ਨਾ ਭੇਜੋ। ਇਸ ਪ੍ਰੋਟੋਟਾਈਪ ਕੋਲ ਕੋਈ ਸਟਾਫ਼ ਲਾਜ਼ਮੀ-ਰਿਪੋਰਟਿੰਗ ਟੀਮ ਨਹੀਂ ਹੈ; ਕਿਸੇ ਭਰੋਸੇਮੰਦ ਬਾਲਗ ਜਾਂ ਸਿਖਲਾਈ ਪ੍ਰਾਪਤ ਵਿਅਕਤੀ ਨੂੰ ਕਾਰਭਾਰ ਸੰਭਾਲਣਾ ਚਾਹੀਦਾ ਹੈ।",
  "intake.childCall": "ਚਾਈਲਡ ਹੈਲਪਲਾਈਨ 1098 'ਤੇ ਕਾਲ ਕਰੋ",
  "intake.childContinue": "ਹਾਨੀਕਾਰਕ ਮੀਡੀਆ ਤੋਂ ਬਿਨਾਂ ਜਾਰੀ ਰੱਖੋ",
  "intake.moneyQ": "ਕੀ ਤੁਹਾਡੇ ਬੈਂਕ ਖਾਤੇ, ਕਾਰਡ, UPI ਐਪ ਜਾਂ ਵਾਲਿਟ ਵਿੱਚੋਂ ਪੈਸੇ ਗਏ ਹਨ?",
  "intake.moneyYes": "ਹਾਂ, ਪੈਸੇ ਗਏ ਹਨ",
