  "intake.urgentH": "ਇੱਥੇ ਰੁకో ਅਤੇ ਵਿੱਤੀ ਧੋਖਾਧੜੀ ਦੀ ਰਿਪੋਰਟ ਹੁਣੇ ਕਰੋ।",
  "intake.urgentBody": "ਜਿੰਨੀ ਜਲਦੀ ਹੋ ਸਕੇ 1930 'ਤੇ ਕਾਲ ਕਰੋ। ਹੈਲਪਲਾਈਨ ਧੋਖਾਧੜੀ ਨੂੰ ਦਰਜ ਕਰ ਸਕਦੀ ਹੈ ਅਤੇ ਸ਼ਾਮਲ ਵਿੱਤੀ ਸੰਸਥਾਵਾਂ ਨੂੰ ਸੁਚੇਤ ਕਰ ਸਕਦੀ ਹੈ; ਇਹ ਖਾਤੇ ਨੂੰ ਸੀਲ ਕਰਨ ਜਾਂ ਪੈਸੇ ਵਾਪਸ ਕਰਨ ਦੀ ਗਰੰਟੀ ਨਹੀਂ ਦੇ ਸਕਦੀ। ਇਸ ਟੈਬ ਨੂੰ ਛੱਡਣ ਤੋਂ ਪਹਿਲਾਂ ਸੇਵ ਸੂਚਕ ਦੀ ਜਾਂਚ ਕਰੋ।",
  "intake.storyQ": "ਹੁਣ ਮੈਨੂੰ ਦੱਸੋ ਕਿ ਕੀ ਹੋਇਆ, ਪਹਿਲੀ ਕਾਲ ਜਾਂ ਸੰਦੇਸ਼ ਤੋਂ ਲੈ ਕੇ ਅੱਗੇ ਕੀ ਹੋਇਆ ਤੱਕ।",
  "intake.storyHint": "ਆਪਣੀ ਭਾਸ਼ਾ ਅਤੇ ਆਮ ਸ਼ਬਦਾਂ ਦੀ ਵਰਤੋਂ ਕਰੋ। ਨਾਮ, ਫੋਨ ਨੰਬਰ, UPI IDs, ਮਿਤੀਆਂ ਅਤੇ ਲੈਣ-ਦੇਣ ਦੇ ਹਵਾਲੇ ਮਦਦ ਕਰਦੇ ਹਨ। ਗੁਪਤ ਜਾਣਕਾਰੀ ਅਤੇ ਪਛਾਣ ਨੰਬਰ ਛੱਡ ਦਿਓ।",
  "intake.storyCta": "ਮੇਰਾ ਕੇਸ ਸਮਝੋ",
  "intake.storyShort": "ਕਿਰਪਾ ਕਰਕੇ ਇੱਕ ਜਾਂ ਦੋ ਹੋਰ ਵੇਰਵੇ ਸ਼ਾਮਲ ਕਰੋ ਤਾਂ ਜੋ ਮੈਨੂੰ ਅੰਦਾਜ਼ਾ ਨਾ ਲਗਾਉਣਾ ਪਵੇ ਕਿ ਕੀ ਹੋਇਆ ਸੀ।",
  "intake.analysing": "ਸਮਾਂ-ਰੇਖਾ, ਪਛਾਣਕਰਤਾ ਅਤੇ ਗੁੰਮਸ਼ੁਦਾ ਤੱਥਾਂ ਨੂੰ ਸੁਣ ਰਿਹਾ ਹੈ",
  "intake.verifyQ": "ਇਹ ਹੈ ਜੋ ਮੈਂ ਸਮਝਿਆ। ਕਿਰਪਾ ਕਰਕੇ ਇਸਨੂੰ ਤੁਹਾਡੀ ਕੇਸ ਫਾਈਲ ਵਿੱਚ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਠੀਕ ਕਰੋ।",
  "intake.verifySub": "ਇੱਕ ਸੁਝਾਅ ਉਦੋਂ ਤੱਕ ਤੱਥ ਨਹੀਂ ਹੁੰਦਾ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇਸਦੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਕਰਦੇ।",
