  "intake.verifyBankAlertHint": "ਇਹ—ਅੰਦਾਜ਼ਨ ਘਟਨਾ ਦੇ ਸਮੇਂ ਦੀ ਬਜਾਏ—ਸ਼ਰਤੀਆ RBI 3 working days ਗਣਨਾ ਲਈ ਟਰਿੱਗਰ ਹੈ। ਜੇਕਰ ਪਤਾ ਨਹੀਂ ਹੈ ਤਾਂ ਇਸਨੂੰ ਖਾਲੀ ਛੱਡ ਦਿਓ।",
