  "intake.sourceRules": "ਆਨ-ਡਿਵਾਈਸ ਨਿਯਮ",
  "intake.rbiInitiationQ": "ਵਿਵਾਦਤ ਭੁਗਤਾਨ ਲਈ, ਕੀ ਤੁਸੀਂ ਇਸਨੂੰ ਖੁਦ ਬਣਾਇਆ ਜਾਂ ਮਨਜ਼ੂਰ ਕੀਤਾ ਸੀ—ਭਾਵੇਂ ਕਿਸੇ ਨੇ ਤੁਹਾਨੂੰ ਧੋਖਾ ਦਿੱਤਾ ਹੋਵੇ ਜਾਂ ਦਬਾਅ ਪਾਇਆ ਹੋਵੇ?",
  "intake.rbiInitiatedMe": "ਮੈਂ ਇਸਨੂੰ ਬਣਾਇਆ ਜਾਂ ਮਨਜ਼ੂਰ ਕੀਤਾ",
  "intake.rbiInitiatedNotMe": "ਮੈਂ ਇਸਨੂੰ ਨਹੀਂ ਬਣਾਇਆ ਜਾਂ ਮਨਜ਼ੂਰ ਕੀਤਾ",
  "intake.rbiCredentialQ": "ਕੀ OTP, PIN, ਪਾਸਵਰਡ ਜਾਂ ਹੋਰ ਭੁਗਤਾਨ ਪ੍ਰਮਾਣ ਪੱਤਰ ਸਾਂਝਾ ਕਰਨ ਨਾਲ ਇਸ ਵਿਵਾਦਤ ਲੈਣ-ਦੇਣ ਦੇ ਹੋਣ ਦਾ ਕਾਰਨ ਜਾਂ ਸਹਾਇਤਾ ਮਿਲੀ ਜਾਪਦੀ ਹੈ? ‘ਪਤਾ ਨਹੀਂ’ ਚੁਣੋ ਜੇਕਰ ਤੁਸੀਂ ਸਿਰਫ਼ ਇਹ ਜਾਣਦੇ ਹੋ ਕਿ ਕੁਝ ਸਾਂਝਾ ਕੀਤਾ ਗਿਆ ਸੀ। ਇਹ ਦੋਸ਼ ਲਗਾਉਣ ਵਾਲਾ ਸਵਾਲ ਨਹੀਂ ਹੈ।",
  "intake.rbiCredentialYes": "ਹਾਂ, ਇਸ ਨਾਲ ਇਹ ਸੰਭਵ ਹੋਇਆ ਜਾਪਦਾ ਹੈ",
  "intake.rbiCredentialNo": "ਨਹੀਂ—ਕੁਝ ਵੀ ਸਾਂਝਾ ਨਹੀਂ ਕੀਤਾ ਗਿਆ ਸੀ, ਜਾਂ ਇਸ ਨਾਲ ਇਹ ਸੰਭਵ ਨਹੀਂ ਹੋਇਆ",
