  "intake.waExclusions": "ਅਨੁਮਾਨ ਵਿੱਚ GST, BSP ਮਾਰਕਅੱਪ, ਟੈਲੀਫੋਨੀ, Vaani ਅਤੇ ਸੰਚਾਲਨ ਖਰਚੇ ਸ਼ਾਮਲ ਨਹੀਂ ਹਨ। ਲਾਂਚ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਮੌਜੂਦਾ Meta ਰੇਟ ਕਾਰਡ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ",
