  "intake.vaaniBody": "Vaani ਇੱਕ ਵਿਕਲਪਿਕ AI ਵਾਇਸ ਪ੍ਰੋਸੈਸਰ ਹੈ, ਪੁਲਿਸ, ਸਰਕਾਰ, ਐਮਰਜੈਂਸੀ ਸੇਵਾ ਜਾਂ ਮਨੁੱਖੀ ਸਲਾਹਕਾਰ ਨਹੀਂ। ਸੁਰੱਖਿਆ ਅਤੇ ਉਮਰ ਦੀਆਂ ਜਾਂਚਾਂ ਪੂਰੀਆਂ ਹੋਣ ਤੱਕ ਆਵਾਜ਼ ਲਾਕ ਰਹਿੰਦੀ ਹੈ, ਅਤੇ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇਸਦੀ ਸਮੀਖਿਆ ਨਹੀਂ ਕਰਦੇ, ਕੋਈ ਵੀ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਤੁਹਾਡੇ ਖਾਤੇ ਵਿੱਚ ਦਾਖਲ ਨਹੀਂ ਹੁੰਦੀ।",
  "intake.vaaniLocked": "ਆਵਾਜ਼ ਹੇਠਾਂ ਦਿੱਤੇ ਤਿੰਨ ਛੋਟੇ ਸਵਾਲਾਂ ਤੋਂ ਬਾਅਦ ਖੁੱਲ੍ਹਦੀ ਹੈ: ਸੀਮਾਵਾਂ ਦਾ ਵਾਅਦਾ, ਕੀ ਤੁਸੀਂ ਇਸ ਸਮੇਂ ਸੁਰੱਖਿਅਤ ਹੋ, ਅਤੇ ਕੀ ਕੋਈ ਬੱਚਾ ਸ਼ਾਮਲ ਹੈ। ਤੁਸੀਂ ਇਸਦੀ ਬਜਾਏ ਟਾਈਪ ਕਰਨਾ ਜਾਰੀ ਰੱਖ ਸਕਦੇ ਹੋ।",
  "intake.vaaniDemo": "Vaani ਇੱਥੇ ਕੌਂਫਿਗਰ ਨਹੀਂ ਹੈ। ਇੰਟਰਵਿਊ ਵਿੱਚ ਮਾਈਕ੍ਰੋਫੋਨ ਦੀ ਵਰਤੋਂ ਕਰੋ, ਜਾਂ ਸਪੱਸ਼ਟ ਤੌਰ 'ਤੇ ਚਿੰਨ੍ਹਿਤ ਨਮੂਨਾ ਕਾਲ ਲੋਡ ਕਰੋ।",
  "intake.vaaniLive": "ਕੰਟਰੋਲਡ Vaani ਟੈਸਟ ਕਾਲਬੈਕ ਅਲਾਉਲਿਸਟ ਕੀਤੇ ਨੰਬਰਾਂ ਲਈ ਉਪਲਬਧ ਹੈ",
  "intake.vaaniLiveBrowser": "ਆਪਣੇ ਮਾਈਕ੍ਰੋਫੋਨ ਦੀ ਵਰਤੋਂ ਕਰਕੇ Kavach Saathi ਨਾਲ ਗੱਲ ਕਰੋ",
  "intake.vaaniPhone": "ਕਾਲ ਕਰਨ ਲਈ ਨੰਬਰ, ਦੇਸ਼ ਦੇ ਕੋਡ ਸਮੇਤ",
  "intake.vaaniSafe": "ਮੇਰੇ ਲਈ ਇਸ ਕਾਲ ਨੂੰ ਪ੍ਰਾਪਤ ਕਰਨਾ ਅਤੇ ਇਸ 'ਤੇ ਬੋਲਣਾ ਹੁਣ ਸੁਰੱਖਿਅਤ ਹੈ।",
  "intake.vaaniConsent": "ਮੈਂ ਇੱਛਤ ਪ੍ਰਾਪਤਕਰਤਾ ਹਾਂ ਅਤੇ ਚਾਹੁੰਦਾ/ਚਾਹੁੰਦੀ ਹਾਂ ਕਿ Kavach Vaani AI ਨੂੰ ਇਸ ਅਲਾਉਲਿਸਟ ਕੀਤੇ ਨੰਬਰ 'ਤੇ ਹੁਣੇ ਕਾਲ ਕਰਨ ਲਈ ਕਹੇ। ਕੈਰੀਅਰ ਦੇ ਖਰਚੇ ਲੱਗ ਸਕਦੇ ਹਨ।",
  "intake.vaaniDataConsent": "ਮੈਂ Vaani ਵੱਲੋਂ ਮੇਰੀ ਕਹੀ ਗੱਲ ਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਨ ਅਤੇ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਕਰਨ ਲਈ ਸਹਿਮਤੀ ਦਿੰਦਾ/ਦਿੰਦੀ ਹਾਂ ਤਾਂ ਜੋ ਮੈਂ ਇੱਥੇ ਕੇਸ ਡ੍ਰাফਟ ਦੀ ਸਮੀਖਿਆ ਕਰ ਸਕਾਂ।",
  "intake.vaaniRecordingConsent": "ਮੈਂ ਸਮਝਦਾ/ਸਮਝਦੀ ਹਾਂ ਕਿ ਇਹ Vaani ਸੈੱਟਅੱਪ ਕਾਲ ਅਤੇ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਨੂੰ ਰਿਕਾਰਡ ਅਤੇ ਰੱਖ ਸਕਦਾ ਹੈ, ਅਤੇ ਮੈਂ ਉਸ ਰਿਕਾਰਡਿੰਗ ਲਈ ਵੱਖਰੇ ਤੌਰ 'ਤੇ ਸਹਿਮਤੀ ਦਿੰਦਾ/ਦਿੰਦੀ ਹਾਂ।",
  "intake.vaaniPrivacy": "Vaani ਦਾ ਪ੍ਰਕਾਸ਼ਿਤ ਗੋਪਨੀਯਤਾ ਨੋਟਿਸ ਕਹਿੰਦਾ ਹੈ ਕਿ ਕਾਲ ਰਿਕਾਰਡਿੰਗਾਂ ਅਤੇ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟਾਂ ਨੂੰ 24 months ਤੱਕ ਰੱਖਿਆ ਜਾ ਸਕਦਾ ਹੈ ਅਤੇ ਡਾਟਾ ਨੂੰ ਭਾਰਤ ਤੋਂ ਬਾਹਰ ਪ੍ਰੋਸੈਸ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ। ਜੇ ਇਹ ਸਵੀਕਾਰਯੋਗ ਨਹੀਂ ਹੈ ਤਾਂ ਸ਼ੁਰੂ ਨਾ ਕਰੋ; ਇਸ ਦੀ ਬਜਾਏ ਟੈਕਸਟ ਦੁਆਰਾ ਜਾਰੀ ਰੱਖੋ। ਉਤਪਾਦਨ ਦੀ ਵਰਤੋਂ ਲਈ ਅਜੇ ਵੀ ਇਕਰਾਰਨਾਮੇ ਦੀ ਪੁਸ਼ਟੀ, ਵਾਪਸੀ ਅਤੇ ਮਿਟਾਉਣ ਦੇ ਕੰਟਰੋਲ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।",
  "intake.vaaniStorageRequired": "ਲਾਈਵ ਕਾਲਬੈਕ ਅਯੋਗ ਹੈ ਕਿਉਂਕਿ ਇਹ ਟੈਬ ਆਈਡੈਂਪੋਟੈਂਸੀ ਰਸੀਦ ਨੂੰ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਕਰ ਸਕਦੀ। ਉਸ ਰਸੀਦ ਤੋਂ ਬინਾਂ, ਚੈਨਲ ਬਦਲਣਾ ਜਾਂ ਦੁਬਾਰਾ ਲੋਡ ਕਰਨਾ ਡੁਪਲੀਕੇਟ ਕਾਲ ਕਰ ਸਕਦਾ ਹੈ। ਟੈਕਸਟ ਦੁਆਰਾ ਜਾਰੀ ਰੱਖੋ ਜਾਂ ਬਿਨਾਂ ਕਾਲ ਵਾਲੇ ਨਮੂਨੇ ਦੀ ਵਰਤੋਂ ਕਰੋ।",
  "intake.vaaniCall": "Vaani ਨੂੰ ਮੈਨੂੰ ਕਾਲ ਕਰਨ ਲਈ ਕਹੋ",
  "intake.vaaniCalling": "ਕਾਲ ਦੀ ਬੇਨਤੀ ਕੀਤੀ ਜਾ ਰਹੀ ਹੈ",
  "intake.vaaniActive": "ਕਾਲ ਦੀ ਬੇਨਤੀ ਕੀਤੀ ਗਈ ਸੀ। ਜਦੋਂ ਇਹ ਸਮਾप्त ਹੋ ਜਾਵੇ, ਤਾਂ ਇਸਦੀ ਸਮੀਖਿਆ ਕਰਨ ਲਈ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਪ੍ਰਾਪਤ ਕਰੋ। ਅਜੇ ਤੱਕ ਤੁਹਾਡੇ ਖਾਤੇ ਵਿੱਚ ਕੁਝ ਵੀ ਦਾਖਲ ਨਹੀਂ ਹੋਇਆ ਹੈ।",
  "intake.vaaniImport": "ਸਮੀਖਿਆ ਲਈ ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਪ੍ਰਾਪਤ ਕਰੋ",
  "intake.vaaniNotReady": "ਟ੍ਰਾਂਸਕ੍ਰਿਪਟ ਤਿਆਰ ਨਹੀਂ ਹੈ ਜਾਂ ਪ੍ਰਦਾਤਾ ਅਸਥਾਈ ਤੌਰ 'ਤੇ ਉਪਲਬਧ ਨਹੀਂ ਹੈ। ਕੋਈ ਦੂਜੀ ਕਾਲ ਨਹੀਂ ਕੀਤੀ ਜਾਵੇਗੀ। ਲਗਭਗ ਇਸ ਤੋਂ ਬਾਅਦ ਦੁਬਾਰਾ ਜਾਂਚ ਕਰੋ",
