  "intake.vaaniReview": "ਪੀੜਤ ਦੇ ਖਾਤੇ ਦੀ ਵਰਤੋਂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਇਸਦੀ ਸਮੀਖਿਆ ਕਰੋ",
  "intake.vaaniReviewSub": "ਏਜੰਟ ਦੇ ਸਵਾਲ ਅਤੇ ਸਪੱਸ਼ਟ ਸਪੀਕਰ ਲੇਬਲ ਫਿਲਟਰ ਕੀਤੇ ਜਾਂਦੇ ਹਨ, ਪਰ ਸਪੀਚ ਪਛਾਣ ਫਿਰ ਵੀ ਗਲਤ ਹੋ ਸਕਦੀ ਹੈ। ਕਿਸੇ ਵੀ ਲਾਈਨ ਨੂੰ ਸੰਪਾਦਿਤ ਕਰੋ ਜਾਂ ਹਟਾਓ। ਇਹ ਟੈਕਸਟ ਉਦੋਂ ਤੱਕ ਸਟੇਜ ਰਹਿੰਦਾ ਹੈ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ 'ਸਮੀਖਿਆ ਕੀਤੇ ਖਾਤੇ ਦੀ ਵਰਤੋਂ ਕਰੋ' ਨਹੀਂ ਚੁਣਦੇ।",
  "intake.vaaniUse": "ਸਮੀਖਿਆ ਕੀਤੇ ਖਾਤੇ ਦੀ ਵਰਤੋਂ ਕਰੋ",
  "intake.vaaniAccepted": "ਸਮੀਖਿਆ ਕੀਤਾ ਖਾਤਾ ਤੁਹਾਡੀ ਕਹਾਣੀ ਵਿੱਚ ਜੋੜਿਆ ਗਿਆ ਸੀ। ਤੁਸੀਂ ਅਜੇ ਵੀ ਹੇਠਾਂ ਦਿੱਤੇ ਹਰੇਕ ਕੱਢੇ ਗਏ ਤੱਥ ਨੂੰ ਸੰਪਾਦਿਤ ਅਤੇ ਪੁਸ਼ਟੀ ਕਰ ਸਕਦੇ ਹੋ।",
  "intake.vaaniUnknown": "ਕਾਲਬੈਕ ਬੇਨਤੀ ਦਾ ਨਤੀਜਾ ਅਣਜਾਣ ਹੈ। ਇਹ ਪਹਿਲਾਂ ਹੀ ਸਵੀਕਾਰ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ, ਇਸ ਲਈ ਇਹ ਪ੍ਰੋਟੋਟਾਈਪ ਇਸਦੀ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਨਹੀਂ ਕਰੇਗਾ ਜਾਂ ਕੋਈ ਹੋਰ ਕਾਲ ਨਹੀਂ ਕਰੇਗਾ। ਇੱਥੇ ਟੈਕਸਟ ਦੁਆਰਾ ਜਾਰੀ ਰੱਖੋ।",
