  "ev.preserveNote": "ਜੇਕਰ ਇਹ ਸੁਰੱਖਿਅਤ ਹੈ, ਤਾਂ ਸੰਪਰਕ ਜਾਰੀ ਰੱਖੇ ਬਿਨਾਂ ਜਾਂ ਜ਼ਰੂਰੀ ਮਦਦ ਵਿੱਚ ਦੇਰੀ ਕੀਤੇ ਬਿਨਾਂ ਅਸਲੀ ਰਿਕਾਰਡ ਸੁਰੱਖਿਅਤ ਰੱਖੋ। ਇਹ ਸਕੋਰ ਤੁਹਾਡੀ ਚੈੱਕਲਿਸਟ ਨੂੰ ਟਰੈਕ ਕਰਦਾ ਹੈ; ਇਹ ਕਾਨੂੰਨੀ ਤੌਰ 'ਤੇ ਕਾਫ਼ੀ ਹੋਣ ਜਾਂ ਅਸਲੀਅਤ ਦਾ ਫ਼ੈਸਲਾ ਨਹੀਂ ਕਰਦਾ।",
