  "ev.storageNote": "ਇੱਥੇ ਨੱਥੀ ਫਾਈਲਾਂ ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਦੇ IndexedDB ਵਿੱਚ ਅਸਲ ਬਾਈਟਾਂ ਵਜੋਂ ਸਟੋਰ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ ਅਤੇ SHA-256 ਨਾਲ ਫਿੰਗਰਪ੍ਰਿੰਟ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਇਹ Kavach ਦੇ ਸਰਵਰ ਜਾਂ AI ਮਾਡਲ ਨੂੰ ਨਹੀਂ ਭੇਜੀਆਂ ਜਾਂਦੀਆਂ। ਸਾਈਟ ਡੇਟਾ ਸਾਫ਼ ਕਰਨ ਨਾਲ ਉਹ ਮਿਟ ਜਾਂਦੀਆਂ ਹਨ; ਅਸਲ ਵਾਲੀਆਂ ਵੀ ਰੱਖੋ।",
  "ev.manifestTitle": "ਪ੍ਰਿੰਟ ਕਰਨ ਯੋਗ ਸਬੂਤ ਮੈਨੀਫੈਸਟ",
  "ev.manifestBody": "ਇੱਕ PDF ਚੈੱਕਲਿਸਟ ਤਿਆਰ ਕਰੋ ਕਿ ਤੁਹਾਡੇ ਕੋਲ ਕੀ ਹੈ, ਕੀ ਗੁੰਮ ਹੈ, ਤੁਹਾਡੀ ਸਮਾਂ-ਸੀਮਾ ਅਤੇ ਉਪਲਬਧ ਫਿੰਗਰਪ੍ਰਿੰਟਸ। PDF ਵਿੱਚ ਸਬੂਤ ਫਾਈਲਾਂ ਸ਼ਾਮਲ ਨਹੀਂ ਹੁੰਦੀਆਂ ਅਤੇ ਇਹ ਕੋਈ ਅਧਿਕਾਰਤ ਸ਼ਿਕਾਇਤ ਨਹੀਂ ਹੈ।",
  "ev.generateSummary": "ਸਬੂਤ ਦਾ ਸਾਰ ਤਿਆਰ ਕਰੋ",
  "ev.checklistH2": "ਸਬੂਤਾਂ ਦੀ ਚੈੱਕਲਿਸਟ",
  "ev.checklistSub": "ਹਰੇਕ ਆਈਟਮ ਦੱਸਦੀ ਹੈ ਕਿ ਇਹ ਕਿਉਂ ਮਹੱਤਵਪੂਰਨ ਹੈ। ਸ਼ਾਮਲ, ਗੁੰਮ ਜਾਂ ਲਾਗੂ ਨਹੀਂ ਵਜੋਂ ਮਾਰਕ ਕਰੋ। PNG, JPG ਜਾਂ PDF (ਵੱਧ ਤੋਂ ਵੱਧ 10 MB) ਨੱਥੀ ਕਰੋ।",
