  "ev.heldElsewhere": "ਕਿਤੇ ਹੋਰ ਰੱਖਿਆ ਗਿਆ ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ; Kavach ਕੋਲ ਇਸ ਆਈਟਮ ਲਈ ਕੋਈ ਸਥਾਨਕ ਫ਼ਾਈਲ ਨਹੀਂ ਹੈ।",
