  "ev.storing": "ਸਟੋਰ ਅਤੇ ਫਿੰਗਰਪ੍ਰਿੰਟ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ...",
  "ev.block.child": "ਇਸ ਬਾਲ-ਸੁਰੱਖਿਆ ਕੇਸ ਲਈ ਸਥਾਨਕ ਨੱਥੀਕਰਨ ਅਯੋਗ ਹੈ। 18 ਸਾਲ ਤੋਂ ਘੱਟ ਉਮਰ ਦੇ ਕਿਸੇ ਵੀ ਵਿਅਕਤੀ ਨਾਲ ਜੁੜੀ ਜਿਨਸੀ ਸਮੱਗਰੀ ਨੂੰ ਅਪਲੋਡ, ਫਾਰਵર્ડ, ਡਾਊਨਲੋਡ ਜਾਂ ਇਸਦੀ ਕੋਈ ਹੋਰ ਕਾਪੀ ਨਾ ਬਣਾਓ। ਸਮੱਗਰੀ ਨੂੰ ਦੁਬਾਰਾ ਖੋੁਲ੍ਹੇ ਬਿਨਾਂ ਸਰੋਤ ਡਿਵਾਈਸ, URL ਜਾਂ ਖਾਤੇ ਦੇ ਵੇਰਵਿਆਂ ਨੂੰ ਸੁਰੱਖਿਅਤ ਰੱਖੋ, ਅਤੇ 1098, 112 ਜਾਂ ਸਿਖਲਾਈ ਪ੍ਰਾਪਤ ਸੁਰੱਖਿਆ ਪੇਸ਼ੇਵਰ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "ev.block.intimate": "ਇਸ ਨਿੱਜੀ-ਸਮੱਗਰੀ ਕੇਸ ਲਈ ਸਥਾਨਕ ਨੱਥੀਕਰਨ ਅਯੋਗ ਹੈ ਤਾਂ ਜੋ Kavach ਕੋਈ ਹੋਰ ਕਾਪੀ ਨਾ ਬਣਾਵੇ। ਸਮੱਗਰੀ ਨੂੰ ਫਾਰਵર્ડ ਕੀਤੇ ਬਿਨਾਂ ਸਰੋਤ ਡਿਵਾਈਸ, URL ਜਾਂ ਖਾਤੇ ਦੇ ਵੇਰਵਿਆਂ ਨੂੰ ਸੁਰੱਖਿਅਤ ਰੱਖੋ। ਤੁਸੀਂ ਅਜੇ ਵੀ ਕਿਸੇ ਆਈਟਮ ਨੂੰ ਕਿਤੇ ਹੋਰ ਰੱਖਿਆ ਗਿਆ ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ ਕਰ ਸਕਦੇ ਹੋ।",
  "ev.err.type": "ਸਿਰਫ਼ PNG, JPG ਅਤੇ PDF ਫ਼ਾਈਲਾਂ ਸਵੀਕਾਰ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।",
  "ev.err.size": "ਫ਼ਾਈਲ ਬਹੁਤ ਵੱਡੀ ਹੈ — ਵੱਧ ਤੋਂ ਵੱਧ 10 MB।",
  "ev.err.empty": "ਫ਼ਾਈਲ ਖਾਲੀ ਹੈ।",
  "ev.err.link": "ਫ਼ਾਈਲ ਬਾਈਟਸ ਲਿੰਕ ਨਹੀਂ ਕੀਤੇ ਗਏ ਸਨ ਕਿਉਂਕਿ ਕੇਸ ਰਿਕਾਰਡ ਨੂੰ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਿਆ। ਪਿਛਲਾ ਨੱਥੀਕਰਨ ਅਪਰਿਵਰਤਿਤ ਹੈ।",
  "ev.err.orphanNew": "ਕੇਸ ਰਿਕਾਰਡ ਨੂੰ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਿਆ ਅਤੇ ਬ੍ਰਾਊਜ਼ਰ ਨਵੇਂ, ਟਰੈਕ ਨਾ ਕੀਤੇ ਸਬੂਤ ਬਾਈਟਸ ਨੂੰ ਨਹੀਂ ਹਟਾ ਸਕਿਆ। ਪਿਛਲਾ ਨੱਥੀਕਰਨ ਅਪਰਿਵਰਤਿਤ ਹੈ। ਬੇਵਾਰਸ ਕਾਪੀ ਨੂੰ ਹਟਾਉਣ ਲਈ Kavach ਸਾਈਟ ਡਾਟਾ ਸਾਫ਼ ਕਰੋ।",
  "ev.err.orphanOld": "ਬਦਲਵੀਂ ਫ਼ਾਈਲ ਸੁਰੱਖਿਅਤ ਹੈ ਅਤੇ ਇਸਦਾ ਫਿੰਗਰਪ੍ਰਿੰਟ ਮੇਲ ਖਾਂਦਾ ਹੈ, ਪਰ ਬ੍ਰਾਊਜ਼ਰ ਪੁਰਾਣੀ ਬੇਵਾਰਸ ਕਾਪੀ ਨੂੰ ਨਹੀਂ ਹਟਾ ਸਕਿਆ। ਤੁਹਾਨੂੰ ਲੋੜੀਂਦੇ ਕਿਸੇ ਵੀ ਅਸਲ ਡਾਟਾ ਨੂੰ ਰੱਖਣ ਤੋਂ ਬਾਅਦ Kavach ਸਾਈਟ ਡਾਟਾ ਸਾਫ਼ ਕਰੋ।",
  "ev.err.removeKept": "ਨੱਥੀਕਰਨ ਰੱਖਿਆ ਗਿਆ ਸੀ ਕਿਉਂਕਿ ਕੇਸ ਰਿਕਾਰਡ ਨੂੰ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਿਆ।",
  "ev.err.removeBytes": "ਨੱਥੀਕਰਨ ਰਿਕਾਰਡ ਹਟਾ ਦਿੱਤਾ ਗਿਆ ਸੀ, ਪਰ ਬ੍ਰਾਊਜ਼ਰ ਬੇਵਾਰਸ ਸਥਾਨਕ ਬਾਈਟਸ ਦੇ ਹਟਾਏ ਜਾਣ ਦੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਕਰ ਸਕਿਆ। ਉਹਨਾਂ ਨੂੰ ਹਟਾਉਣ ਲਈ Kavach ਸਾਈਟ ਡਾਟਾ ਸਾਫ਼ ਕਰੋ।",
  "ev.err.recordOnly": "ਸਿਰਫ਼ ਫ਼ਾਈਲ ਰਿਕਾਰਡ ਉਪਲਬਧ ਹੈ। ਇਸਦੇ ਬਾਈਟਸ ਨੂੰ ਇੱਥੇ ਸਟੋਰ ਕਰਨ ਲਈ ਅਸਲ ਫ਼ਾਈਲ ਨੂੰ ਦوبਾਰਾ ਨੱਥੀ ਕਰੋ।",
  "ev.err.gone": "ਫ਼ਾਈਲ ਹੁਣ ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਨਹੀਂ ਹੈ। ਇਹ ਸਾਈਟ ਡਾਟਾ ਨਾਲ ਹਟਾ ਦਿੱਤੀ ਗਈ ਹੋ ਸਕਦੀ ਹੈ।",
