  "ev.err.removeLocal": "ਸਥਾਨਕ ਫ਼ਾਈਲ ਨੂੰ ਹਟਾਇਆ ਨਹੀਂ ਜਾ ਸਕਿਆ।",
  "ev.tpl.txn_screenshot.title": "ਲੈਣ-ਦੇਣ ਦਾ ਸਕ੍ਰੀਨਸ਼ਾਟ",
