  "ev.tpl.utr_reference.why": "ਸੰਬੰਧਿਤ ਭੁਗਤਾਨ ਭਾਗੀਦਾਰਾਂ ਨੂੰ ਉਹੀ ਲੈਣ-ਦੇਣ ਦੀ ਪਛਾਣ ਕਰਨ ਅਤੇ ਟਰੇਸ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ।",
