  "ev.tpl.sms_notification.why": "ਇਹ ਸਥਾਪਤ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ ਕਿ ਤੁਹਾਨੂੰ ਬੈਂਕ ਦਾ ਸੰਚਾਰ ਕਦੋਂ ਪ੍ਰਾਪਤ ਹੋਇਆ ਸੀ, ਜੋ RBI ਦੇ ਸ਼ਰਤੀਆ ਦੇਣਦਾਰੀ ਵਿਸ਼ਲੇਸ਼ਣ ਵਿੱਚ ਮਹੱਤਵਪੂਰਨ ਹੋ ਸਕਦਾ ਹੈ।",
