  "ev.tpl.chat_screenshot.why": "ਦਿਖਾਏ ਗਏ ਵਾਅਦੇ, ਧੋਖੇਬਾਜ਼ੀ ਜਾਂ ਹਦਾਇਤਾਂ ਨੂੰ ਸੁਰੱਖਿਅਤ ਰੱਖਦਾ ਹੈ; ਇਕੱਲਾ ਸਕ੍ਰੀਨਸ਼ੌਟ ਇਹ ਸਾਬਤ ਨਹੀਂ ਕਰਦਾ ਕਿ ਖਾਤੇ ਨੂੰ ਕਿਸਨੇ ਕੰਟਰੋਲ ਕੀਤਾ।",
