  "ev.tpl.email_correspondence.description": "ਧੋਖੇਬਾਜ਼ ਵੱਲੋਂ ਕੋਈ ਵੀ ਈਮੇਲ ਜਾਂ ਪੱਤਰ।",
  "ev.tpl.email_correspondence.why": "ਸੁਨੇਹੇ ਦੀ ਸਮੱਗਰੀ ਅਤੇ, ਜਿੱਥੇ ਉਪਲਬਧ ਹੋਵੇ, ਤਕਨੀਕੀ ਹੈਡਰਾਂ ਨੂੰ ਸੁਰੱਖਿਅਤ ਰੱਖਦਾ ਹੈ ਜਿਨ੍ਹਾਂ ਦੀ ਜਾਂਚਕਰਤਾ ਜਾਂਚ ਕਰ ਸਕਦਾ ਹੈ।",
